import { expect, test } from "@playwright/test";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// The favicon files (UI redesign step 6): favicon.svg must stay valid XML, match the in-app BrandMark geometry and the
// accent tokens of both themes; favicon.ico (generated by scripts/generate-favicon.mjs) must hold 16, 32 and 48 px PNGs.

const read = (path: string) => readFileSync(fileURLToPath(new URL(`../../${path}`, import.meta.url)));
const svg = read("apps/web/public/favicon.svg").toString("utf8");
const icons = read("apps/web/src/components/icons.tsx").toString("utf8");
const tokens = read("apps/web/src/styles/tokens.css").toString("utf8");

function tokenBlock(selector: string): Record<string, string> {
  const start = tokens.indexOf(`${selector} {`);
  const body = tokens.slice(start, tokens.indexOf("\n}", start));
  return Object.fromEntries([...body.matchAll(/(--[a-z0-9-]+):\s*(#[0-9a-f]{6})\b/gi)].map(([, n, v]) => [n!, v!.toLowerCase()]));
}

/** The fill of a class rule in a CSS text, e.g. `.ticket { fill: #635bdb; }`. */
function fill(css: string, className: string): string | undefined {
  return css.match(new RegExp(`\\.${className}\\s*\\{\\s*fill:\\s*(#[0-9a-f]{6})`, "i"))?.[1]?.toLowerCase();
}

test.describe("favicon.svg", () => {
  test("is well-formed: no '--' inside XML comments, one root svg element", () => {
    for (const [, comment] of svg.matchAll(/<!--([\s\S]*?)-->/g)) {
      expect(comment).not.toContain("--");
    }
    expect(svg.trim()).toMatch(/^<svg [^>]*xmlns="http:\/\/www\.w3\.org\/2000\/svg"[\s\S]*<\/svg>$/);
  });

  test("uses the accent and on-accent tokens: light by default, dark under prefers-color-scheme: dark", () => {
    const light = tokenBlock(":root");
    const dark = { ...light, ...tokenBlock(':root[data-theme="dark"]') };
    const [lightCss, darkCss] = svg.split("@media (prefers-color-scheme: dark)");
    expect(fill(lightCss!, "ticket")).toBe(light["--color-accent"]);
    expect(fill(lightCss!, "bar")).toBe(light["--color-on-accent"]);
    expect(fill(darkCss!, "ticket")).toBe(dark["--color-accent"]);
    expect(fill(darkCss!, "bar")).toBe(dark["--color-on-accent"]);
  });

  test("has the same geometry as the in-app BrandMark", () => {
    const shapes = (source: string) => ({
      viewBox: source.match(/viewBox="([^"]+)"/)?.[1],
      ticket: source.match(/<path[^>]*\sd="([^"]+)"/)?.[1],
      bars: [...source.matchAll(/<rect[^>]*?x="([\d.]+)" y="([\d.]+)" width="([\d.]+)" height="([\d.]+)" rx="([\d.]+)"/g)].map(
        (m) => m.slice(1).join(","),
      ),
    });
    const brandMark = icons.slice(icons.indexOf("export function BrandMark"));
    const favicon = shapes(svg);
    expect(favicon.bars).toHaveLength(3);
    expect(shapes(brandMark)).toEqual(favicon);
  });
});

test.describe("favicon.ico", () => {
  const ico = read("apps/web/public/favicon.ico");

  test("holds 16, 32 and 48 px PNG images with consistent offsets", () => {
    expect(ico.readUInt16LE(0)).toBe(0);
    expect(ico.readUInt16LE(2)).toBe(1);
    const count = ico.readUInt16LE(4);
    expect(count).toBe(3);
    let expectedOffset = 6 + 16 * count;
    const sizes: number[] = [];
    for (let i = 0; i < count; i += 1) {
      const entry = 6 + 16 * i;
      const size = ico.readUInt8(entry);
      const length = ico.readUInt32LE(entry + 8);
      const offset = ico.readUInt32LE(entry + 12);
      expect(ico.readUInt8(entry + 1)).toBe(size);
      expect(offset).toBe(expectedOffset);
      const png = ico.subarray(offset, offset + length);
      expect([...png.subarray(0, 8)]).toEqual([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
      expect(png.readUInt32BE(16)).toBe(size); // IHDR width
      expect(png.readUInt32BE(20)).toBe(size); // IHDR height
      sizes.push(size);
      expectedOffset += length;
    }
    expect(sizes).toEqual([16, 32, 48]);
    expect(ico.length).toBe(expectedOffset);
  });
});
